// plays a note, generated by its instrument, or the piano sound file re-pitched
void play_music_note(ecs* world, entity note, float fade) {
    if (!zox_valid(note) || !zox_has(note, Note)) {
        return;
    }
    const int music_note = zox_getv(note, SoundFrequencyIndex);
    const float note_volume = zox_getv(note, SoundVolume);
    const float note_time = zox_getv(note, SoundLength);
    if (!music_note || !note_volume || !note_time) {
        return;
    }
    const float volume = note_volume * get_volume_music() * fade;
    const byte instrument = zox_getv(note, InstrumentType);
    const float frequency = note_frequencies[music_note];
    if (instrument == instrument_piano_file) {
        spawn_sound_from_file_name(world, prefab_sound, "piano", frequency, volume);
    } else {
        spawn_sound_generated(world, prefab_sound_generated, instrument, frequency, note_time, volume);
    }
}

// a music's loop length: its MusicLength, or when its last note ends
static inline double get_music_length(ecs* world, entity music, const ordered_children* notes) {
    const double length = zox_getv(music, MusicLength);
    if (length > 0) {
        return length;
    }
    double end = 0;
    for (int j = 0; j < notes->length; j++) {
        const entity note = notes->value[j];
        const double note_end = zox_getv(note, NoteStart) + zox_getv(note, SoundLength);
        end = note_end > end ? note_end : end;
    }
    return end;
}

// Plays each music's notes as its playhead passes their starts, any number at once (chords, overlaps)
//  - MusicTime is the playhead (seconds), MusicNote the next note, notes are in order of start
//  - after its length it loops back to the start
zox_sys2(MusicPlaySystem) {
    if (nomusic || nosounds) {
        return;
    }
    const float volume_music = get_volume_music();
    init_delta_time();
    zox_sys_world();
    zox_sys_begin();
    zox_sys_in(MusicEnabled);
    zox_sys_out(MusicNote);
    zox_sys_out(MusicTime);
    for (int i = 0; i < it->count; i++) {
        zox_sys_e();
        zox_sys_i(MusicEnabled, playing);
        zox_sys_o(MusicNote, next);
        zox_sys_o(MusicTime, playhead);
        if (!playing->value) {
            continue;
        }
        // NOTE: Notes are ordered children, by start
        ordered_children notes = zox_get_ordered_children(world, e);
        if (!notes.length) {
            continue;
        }
        const double length = get_music_length(world, e, &notes);
        if (length <= 0) {
            continue;
        }
        // crossfades scale it (MusicFadeSystem), silent music still moves on
        const float fade = zox_has(e, MusicVolume) ? zox_getv(e, MusicVolume) : 1;
        const byte audible = volume_music > 0 && fade > 0;
        playhead->value += delta_time * global_music_speed;
        // at most one loop a frame (a long hitch skips ahead, it doesn't play the song twice)
        for (int loop = 0; loop < 2; loop++) {
            while (next->value < (uint) notes.length) {
                const entity note = notes.value[next->value];
                if (zox_getv(note, NoteStart) > playhead->value) {
                    break;
                }
                if (audible) {
                    play_music_note(world, note, fade);
                }
                next->value++;
            }
            if (playhead->value < length) {
                break;
            }
            playhead->value = fmod(playhead->value - length, length);
            next->value = 0;
        }
    }
} zox_sys_end(MusicPlaySystem);

// Eases each music's volume to its target, a faded out music stops playing
zox_sys2(MusicFadeSystem) {
    init_delta_time();
    zox_sys_begin();
    zox_sys_in(MusicVolumeTarget);
    zox_sys_out(MusicVolume);
    zox_sys_out(MusicEnabled);
    const float step = (float) (delta_time / music_fade_seconds);
    for (int i = 0; i < it->count; i++) {
        zox_sys_i(MusicVolumeTarget, target);
        zox_sys_o(MusicVolume, volume);
        zox_sys_o(MusicEnabled, enabled);
        if (!enabled->value || volume->value == target->value) {
            continue;
        }
        if (volume->value < target->value) {
            volume->value = float_min(target->value, volume->value + step);
        } else {
            volume->value = float_max(target->value, volume->value - step);
        }
        if (volume->value <= 0 && target->value <= 0) {
            enabled->value = 0;
        }
    }
} zox_sys_end(MusicFadeSystem);
